(() => {
  'use strict';
  TwoAgI18n.register({
    'Language':'语言','Auto / System':'自动 / 跟随系统','Welcome to 2Ag':'欢迎使用 2Ag',
    'Observe · Control · Manage · Customize':'观察 · 控制 · 管理 · 定制',
    'A local enhancement and control layer for Google Antigravity.':'Google Antigravity 的本地桌面增强与控制层。',
    'Environment check':'环境检查','Choose runtime':'选择运行形态','Ready':'就绪',
    'Missing':'未安装','Needs setup':'需要设置','Unavailable':'不可用','Unknown':'未知',
    'Available':'可用','Partial':'部分可用','Disabled':'已关闭','Unsupported':'不支持',
    'Local storage':'本地存储','Enhanced host':'增强宿主','Back':'上一步','Next':'下一步',
    'Open Manager':'打开 Manager','Create Enhanced Host':'建立增强宿主','Start Antigravity':'启动 Antigravity',
    'Reopen welcome':'重新打开欢迎页','Compatibility / Capabilities':'兼容性 / 能力状态',
    'Configured':'配置','Supported':'支持情况','Effective':'当前生效',
    'Official uses your installed Antigravity without runtime UI injection.':'Official 使用已安装的 Antigravity，不注入 2Ag 界面。',
    'Enhanced uses a local frozen host copy with G-Hub and runtime enhancements.':'Enhanced 使用本地冻结宿主副本，提供 G-Hub 与运行时增强。',
    'Choosing a mode saves configuration only. It never starts or restarts a host.':'选择模式只保存配置，不会启动或重启宿主。',
    'Use the explicit start button when ready. Existing Antigravity instances stay running.':'准备好后主动点击启动按钮。已有 Antigravity 实例会保持运行。',
    'Checking…':'检查中…','Saving…':'保存中…','Save failed':'保存失败',
    'Setup failed':'设置失败','Create copy (no launch)':'建立副本（不启动）',
    'Readings come from existing runtime, Doctor, storage and quota probes.':'读数来自已有 Runtime、Doctor、存储与配额探针。',
    'No live reading':'暂无实时读数','No current runtime reading':'暂无当前运行时读数',
    'Capability':'能力','Evidence':'证据','Activity Observability':'执行可观察性',
    'SQLite History':'SQLite 历史','Context Usage':'上下文用量','Quota Probe':'配额探测',
    'Host Translation':'宿主汉化','Extensions':'扩展','Sessions':'会话',
    'Native SQLite file observed; step readability is not yet verified':'发现原生 SQLite 文件，尚未验证步骤可读性',
    'Catalog readable; runtime execution is not confirmed':'扩展目录可读，运行时执行尚未确认',
    'Cached readings only':'仅缓存读数','Live quota reading observed':'已取得实时配额读数',
    'Source readable; no sessions found':'来源可读，尚未发现会话',
    'Refresh':'刷新','Version':'版本','{count} sessions':'{count} 个会话'
  });
  const esc = value => String(value ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const languageSelect = () => '<select data-ui-language data-i18n-aria-label="Language" aria-label="'+esc(t('Language'))+'"><option value="auto" data-i18n="Auto / System">'+t('Auto / System')+'</option><option value="en-US">English</option><option value="zh-CN">简体中文</option></select>';
  const toolbar=document.querySelector('.header-toolbar');
  toolbar.insertAdjacentHTML('afterbegin',languageSelect());
  const welcome=document.createElement('dialog'); welcome.className='readiness-dialog';document.body.append(welcome);
  const summary=document.createElement('section');summary.className='section';summary.id='launch-capabilities';document.getElementById('dash-hero-host').after(summary);
  const reopen=document.createElement('button');reopen.className='btn btn-tonal';reopen.dataset.i18n='Reopen welcome';reopen.addEventListener('click',()=>openWelcome());toolbar.append(reopen);
  document.head.insertAdjacentHTML('beforeend','<style>.readiness-dialog{width:min(540px,85vw);max-height:85vh;overflow:auto;border:1px solid var(--border-color,#dadce0);border-radius:12px;padding:26px;background:var(--bg-primary,#fff);color:var(--text-primary,#202124)}.readiness-dialog::backdrop{background:#0005}.readiness-dialog h2{margin-top:0}.readiness-dialog p{line-height:1.7;color:var(--text-secondary)}.readiness-actions{display:flex;gap:8px;justify-content:flex-end;margin-top:22px;flex-wrap:wrap}.readiness-dialog label{display:block;margin:12px 0}.readiness-status{font-size:12px;line-height:1.6;color:var(--text-secondary)}.header-toolbar select{max-width:150px;padding:5px;border:1px solid var(--border-color,#dadce0);border-radius:5px;background:var(--bg-primary);color:var(--text-primary)}[lang="en-US"] .tab-latin{display:none}#launch-capabilities table{width:100%;font-size:12px;border-collapse:collapse}#launch-capabilities td,#launch-capabilities th{padding:7px 4px;text-align:left;border-bottom:1px solid var(--border-color,#eee)}#launch-capabilities td:last-child{color:var(--text-secondary)}.readiness-error{color:var(--google-red,#c5221f)}</style>');
  let step=0, data=null, capabilities=null, busy=false, error='', initialized=false;
  async function json(path,options){const r=await twoAgFetch(path,options);if(!r.ok)throw Error(await r.text());return r.json();}
  async function action(type,payload){const response=await twoAgFetch('/api/v1/action',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({type,payload})});if(!response.ok)throw Error(await response.text());}
  async function waitSaved(){for(let i=0;i<40;i++){const p=await json('/api/v1/persistence');if(p.status==='saved')return;if(p.status==='save_failed')throw Error(p.error||'Configuration could not be saved');await new Promise(r=>setTimeout(r,100));}throw Error('Configuration save is still pending');}
  async function changeLanguage(value){if(busy)return;const previous=TwoAgI18n.preference;let accepted=false;busy=true;error='';globalState.language=value;TwoAgI18n.set(value);document.querySelectorAll('[data-ui-language]').forEach(node=>node.disabled=true);try{await action('SET_LANGUAGE',{language:value});accepted=true;await waitSaved();}catch(e){if(!accepted){globalState.language=previous;TwoAgI18n.set(previous);}error=e.message;logMsg(t('Save failed')+': '+e.message,'term-err');}finally{busy=false;paintWelcome();document.querySelectorAll('[data-ui-language]').forEach(node=>node.disabled=false);}}
  document.addEventListener('change',event=>{if(event.target.matches('[data-ui-language]'))void changeLanguage(event.target.value);});
  async function load(){try{data=await json('/api/v1/launch-readiness');paintWelcome();const [cap,runtime,sessions,accounts,extensions]=await Promise.allSettled(['/api/v1/capability','/api/v1/context','/api/v1/sessions','/api/v1/accounts','/api/v1/extensions/local'].map(p=>json(p)));capabilities={cap:cap.value,runtime:runtime.value,sessions:sessions.value,accounts:accounts.value,extensions:extensions.value};paintSummary();}catch(e){error=e.message;paintWelcome();paintSummary();}}
  function environmentRows(){const b=data?.bootstrap||{},storage=data?.doctor?.checks?.find(c=>c.id==='storage');return [['Antigravity',data?b.official_present?'Ready':'Missing':'Unknown'],['WebView2',data?data.webview2?'Ready':'Unavailable':'Unknown'],['Local storage',data?storage?.state==='ok'?'Ready':'Unavailable':'Unknown'],['Enhanced host',data?b.frozen_host_present?'Ready':b.official_present?'Needs setup':'Unavailable':'Unknown']];}
  function paintWelcome(){if(!welcome.open)return;const titles=['Welcome to 2Ag','Environment check','Choose runtime','Ready'];let body='';
    if(step===0)body='<p>'+t('A local enhancement and control layer for Google Antigravity.')+'</p><p>'+t('Observe · Control · Manage · Customize')+'</p>'+languageSelect();
    if(step===1)body=environmentRows().map(([name,status])=>'<div class="cluster-row"><span>'+esc(t(name))+'</span><span>'+esc(t(status))+'</span></div>').join('')+'<p>'+esc(data?.webview2||'')+'</p>';
    if(step===2)body=['official','enhanced'].map(mode=>'<label><input type="radio" name="welcome-mode" value="'+mode+'" '+((globalState.runtime_mode||data?.configured_mode)==mode?'checked':'')+' '+(busy?'disabled':'')+'> '+(mode==='official'?'Official':'Enhanced')+'</label><p>'+t(mode==='official'?'Official uses your installed Antigravity without runtime UI injection.':'Enhanced uses a local frozen host copy with G-Hub and runtime enhancements.')+'</p>').join('')+'<p>'+t('Choosing a mode saves configuration only. It never starts or restarts a host.')+'</p>';
    if(step===3)body='<p>'+t('Use the explicit start button when ready. Existing Antigravity instances stay running.')+'</p>';
    welcome.innerHTML='<div class="readiness-status">'+(step+1)+' / 4</div><h2>'+t(titles[step])+'</h2>'+body+'<div class="readiness-status readiness-error" role="status">'+esc(error)+'</div><div class="readiness-actions">'+(step?'<button data-welcome-back '+(busy?'disabled':'')+'>'+t('Back')+'</button>':'')+(step<3?'<button data-welcome-next '+(busy?'disabled':'')+'>'+t('Next')+'</button>':'<button data-welcome-finish '+(busy?'disabled':'')+'>'+t('Open Manager')+'</button>'+(!data?.bootstrap?.frozen_host_present&&data?.bootstrap?.official_present?'<button data-welcome-create '+(busy?'disabled':'')+'>'+t('Create Enhanced Host')+'</button>':'')+'<button data-welcome-start '+(busy||!data?.bootstrap?.official_present&&!data?.bootstrap?.frozen_host_present?'disabled':'')+'>'+t('Start Antigravity')+'</button>')+'</div>';
    TwoAgI18n.apply(welcome);
    welcome.querySelectorAll('[data-ui-language]').forEach(node=>node.disabled=busy);
  }
  async function finish(){busy=true;paintWelcome();try{await action('COMPLETE_ONBOARDING',{});await waitSaved();globalState.onboarding_version=1;welcome.close();}catch(e){error=e.message;}finally{busy=false;paintWelcome();}}
  async function openWelcome(){step=0;error='';if(!welcome.open)welcome.showModal();paintWelcome();void load();}
  welcome.addEventListener('click',async event=>{const button=event.target.closest('button');if(!button||busy)return;if(button.hasAttribute('data-welcome-back')){step--;paintWelcome();}if(button.hasAttribute('data-welcome-next')){step++;paintWelcome();}if(button.hasAttribute('data-welcome-finish'))await finish();if(button.hasAttribute('data-welcome-start')){await finish();if(!welcome.open)operateHost('launch',button);}if(button.hasAttribute('data-welcome-create')){busy=true;paintWelcome();try{await json('/api/v1/host/create-enhanced',{method:'POST'});await load();}catch(e){error=e.message;}finally{busy=false;paintWelcome();}}});
  welcome.addEventListener('change',async event=>{if(event.target.name!=='welcome-mode'||busy)return;busy=true;error='';const mode=event.target.value;paintWelcome();try{await action('SET_RUNTIME_MODE',{mode:mode});await waitSaved();globalState.runtime_mode=mode;renderState();}catch(e){error=e.message;}finally{busy=false;paintWelcome();}});
  function paintSummary(){const c=capabilities,g=c?.cap?.guardian,target=c?.runtime?.targets?.find(t=>t.context?.session_id)||c?.runtime?.targets?.find(t=>t.connected),matrix=g?.capabilities||[];
    const probe=id=>{const item=matrix.find(c=>c.id===id);return item?{OK:'Ready',DEGRADED:'Partial',FAILED:'Unavailable',UNSUPPORTED:'Unsupported',UNKNOWN:'Unknown'}[item.state]||'Unknown':'Unknown';};
    const context=target?.context,stores=data?.environment?.conversation_stores||[],sql=data?.environment?.conversation_formats?.includes('sqlite'),accounts=Array.isArray(c?.accounts)?c.accounts:c?.accounts?.accounts||[],quota=accounts.flatMap(a=>[a.gemini_pool,a.claude_pool]).filter(p=>p?.available),list=Array.isArray(c?.sessions)?c.sessions:c?.sessions?.sessions;
    const rows=[['CDP Runtime',target?.connected?'Ready':context?.source?'Available':probe('CDP_AVAILABLE'),target?.connected?'CDP':context?.source?'Read-only snapshot':'No current runtime reading'],['G-Hub Injection',target?.hub_active?'Ready':probe('G_HUB'),'G_HUB'],['Activity Observability',sql?'Partial':'Unknown',sql?'Native SQLite file observed; step readability is not yet verified':'No live reading'],['SQLite History',sql?'Available':'Unknown','environment.conversation_formats'],['Context Usage',context?.request?'Available':context?.view_available?'Partial':'Unknown',context?.source||'No current runtime reading'],['Quota Probe',quota.some(p=>p.source?.startsWith('live'))?'Ready':quota.length?'Partial':'Unknown',quota.some(p=>p.source?.startsWith('live'))?'Live quota reading observed':quota.length?'Cached readings only':'No live reading'],['Sessions',list?.length?'Ready':stores.length?'Available':data?'Unavailable':'Unknown',list?.length?t('{count} sessions',{count:list.length}):stores.length?'Source readable; no sessions found':'No live reading'],['Host Translation',probe('LOCALIZATION_ROOT'),'LOCALIZATION_ROOT'],['Extensions','Unknown',c?.extensions?'Catalog readable; runtime execution is not confirmed':'No live reading']];
    summary.innerHTML='<div class="section-head"><h3>'+t('Compatibility / Capabilities')+'</h3><button class="btn btn-tonal" data-cap-refresh>'+t('Refresh')+'</button></div><div class="section-note">2Ag '+esc(data?.version||'—')+' · Antigravity '+esc(g?.fingerprint?.running_version||data?.environment?.version||'—')+'</div><div class="section-note">'+t('Configured')+': '+esc(globalState.runtime_mode||data?.configured_mode||'—')+' · '+t('Effective')+': '+esc(g?.fingerprint?.running_pid?g.fingerprint.mode:'—')+'</div><table><thead><tr><th>'+t('Capability')+'</th><th>'+t('Configured')+'</th><th>'+t('Supported')+'</th><th>'+t('Effective')+'</th><th>'+t('Evidence')+'</th></tr></thead><tbody>'+rows.map(([name,status,evidence])=>'<tr><td>'+t(name)+'</td><td>'+t(name==='Host Translation'?(globalState.gravity_boost?.force_zh_cn?'Enabled [ON]':'Disabled [OFF]'):name==='G-Hub Injection'?(globalState.runtime_mode==='official'?'Disabled':'Enabled [ON]'):'—')+'</td><td>'+t(name==='Extensions'?(c?.extensions?'Available':'Unknown'):status)+'</td><td>'+t(status)+'</td><td>'+esc(t(evidence))+'</td></tr>').join('')+'</tbody></table><p class="section-note">'+t('Readings come from existing runtime, Doctor, storage and quota probes.')+'</p>';
    summary.querySelector('[data-cap-refresh]').addEventListener('click',()=>void load());
  }
  async function repaint(){TwoAgI18n.apply();paintWelcome();paintSummary();renderState();if(typeof currentAccounts!=='undefined'){renderAccounts(currentAccounts);updateDashboardPools(currentAccounts);}loadSessions();loadVault();pollBrokerStatus();loadActiveAccount();refreshWallpaperStatus();refreshPersistenceStatus();loadCompat();loadGuardian();loadCapability();probeRealHost();window.dispatchEvent(new Event('2ag:observability-locale'));}
  window.addEventListener('2ag:locale',()=>{if(initialized)void repaint();});
  window.addEventListener('2ag:state',()=>{if(initialized){paintWelcome();paintSummary();}});
  TwoAgI18n.ready.then(async()=>{await new Promise(r=>setTimeout(r,0));const cfg=await json('/api/v1/state');globalState=cfg;TwoAgI18n.set(cfg.language);initialized=true;await repaint();void load();if(cfg.onboarding_version===0)await openWelcome();});
  window.TwoAgReadiness={reload:load,openWelcome};
})();
